// Фінальна збірка: 1 item = 1 HTTP-запит (клієнт + тип кампанії).
const TYPES = ['male', 'female', 'general'];
const norm = (v) => String(v ?? '').trim();

// apiKeys: clientKey -> перший непорожній ключ
// CS PDCA: колонка E = 'col_5' (workspace id), колонка F = 'col_6' (API key)
const apiKeys = {};
for (const item of $input.all()) {
  const row = item.json;
  const clientKey = norm(row['col_5']);
  const key = norm(row['col_6']);
  if (clientKey && key && !(clientKey in apiKeys)) apiKeys[clientKey] = key;
}

const out = [];
for (const item of $('Combine client data').all()) {
  const c = item.json;
  const apiKey = apiKeys[norm(c.clientKey)];
  if (!apiKey) {
    console.log(`Клієнт ${c.clientKey}: API key не знайдено. Є ключі для: ${Object.keys(apiKeys).join(', ') || '(нічого)'}`);
    continue;
  }
  for (const type of TYPES) {
    const leadIds = c[type] || [];
    const campaignId = c.campaigns[type];
    if (!leadIds.length || !campaignId) continue;
    out.push({
      json: {
        clientKey: c.clientKey,
        type,
        campaignId,
        apiKey,
        leadIds: leadIds.map((v) => (v !== '' && !isNaN(Number(v)) ? Number(v) : v)),
      },
    });
  }
}
return out;

// Об'єднуємо кампанії з ARM із згрупованими лідами → знову 1 item на клієнта.
const TYPES = ['male', 'female', 'general'];
const norm = (v) => String(v ?? '').trim();

// campaigns: clientKey -> { male: campaignId, female: ..., general: ... }
const campaigns = {};
for (const item of $input.all()) {
  const row = item.json;
  const clientKey = norm(row['bison workspace id']);
  const campaignId = norm(row['bison ooo campaign id']);
  const type = norm(row['gender']).toLowerCase();
  if (!clientKey || !campaignId || !TYPES.includes(type)) continue;
  if (!campaigns[clientKey]) campaigns[clientKey] = {};
  if (!(type in campaigns[clientKey])) campaigns[clientKey][type] = campaignId;
}

const out = [];
for (const item of $('Group leads by client').all()) {
  const c = item.json;
  const clientCampaigns = campaigns[norm(c.clientKey)];
  if (!clientCampaigns) {
    console.log(`Клієнт ${c.clientKey}: кампаній в ARM не знайдено. Є ключі: ${Object.keys(campaigns).join(', ')}`);
    continue;
  }
  out.push({ json: { ...c, campaigns: clientCampaigns } });
}
return out;

// Агрегація: з N лідів робимо 1 item на клієнта (workspace).
const TYPES = ['male', 'female', 'general'];
const norm = (v) => String(v ?? '').trim();

const clients = {};
for (const item of $input.all()) {
  const row = item.json;
  const leadId = norm(row.LeadID);
  const clientKey = norm(row.WorkspaceID);
  let gender = norm(row.Gender).toLowerCase();
  if (!gender) gender = 'general'; // порожній gender → general

  if (!clientKey || !leadId) continue;
  if (!clients[clientKey]) clients[clientKey] = { male: [], female: [], general: [] };
  if (TYPES.includes(gender)) clients[clientKey][gender].push(leadId);
}

return Object.entries(clients)
  .filter(([, b]) => b.male.length || b.female.length || b.general.length)
  .map(([clientKey, b]) => ({ json: { clientKey, ...b } }));
